def solve(s) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Accepts any input; non-string inputs are treated as having no brackets.
    """
    if not isinstance(s, str):
        return True
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

