def solve(intervals):
    """Merge overlapping or adjacent intervals.
    Handles intervals where start may be greater than end by swapping.
    Returns [] for invalid input types.
    """
    if not isinstance(intervals, list):
        return []
    valid = []
    for iv in intervals:
        if isinstance(iv, (list, tuple)) and len(iv) == 2:
            a, b = iv
            try:
                # Ensure numeric
                a_num = a
                b_num = b
            except Exception:
                continue
            # Swap if out of order
            if a_num > b_num:
                a_num, b_num = b_num, a_num
            valid.append([a_num, b_num])
    if not valid:
        return []
    valid.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = valid[0]
    for start, end in valid[1:]:
        if start <= cur_end:
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

