def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles None or non-list inputs by treating them as empty.
    Implements O(n log n) algorithm for large inputs.
    """
    if not nums:
        return 0
    # Ensure we have an iterable of ints
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # Find position to replace in tails
        pos = bisect.bisect_left(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

