def solve(s=''):
    """Run-length encoding.
    Accepts missing argument, None, or non-string by converting to string.
    Returns a list of [character, count] pairs.
    """
    if s is None:
        s = ''
    if not isinstance(s, str):
        s = str(s)
    if not s:
        return []
    res = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

