    """Count islands in binary grid, robust handling of invalid inputs.
    Returns 0 for non-list or empty inputs.
    """
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if isinstance(grid[0], list) else 0
    if cols == 0:
        return 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        visited[r][c] = True
        while stack:
            x,y = stack.pop()
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx,ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny]==1:
                    visited[nx][ny] = True
                    stack.append((nx,ny))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                islands += 1
                dfs(i,j)
